seres.')});els.manualLock.addEventListener('change',()=>{dirtyDays.add(activeDate());manualLocks[activeDate()]=els.manualLock.checked;delete optimizationState[activeDate()];renderPlan();if(!els.manualLock.checked)scheduleOptimization(activeDate(),'unlock',80);else setStatus('Ordem manual fixada para '+labelDate(activeDate())+'.','success')});
